package com.motionstudio.part2
import kotlin.math.*
data class Particle(var x:Float,var y:Float,var vx:Float,var vy:Float,var ax:Float,var ay:Float,var age:Float,var life:Float,var size:Float,var rotation:Float,var opacity:Float,var color:Rgba)
data class Emitter(val x:Float,val y:Float,val rate:Float=20f,val lifetime:Float=1f,val speed:Float=50f,val spread:Float=PI.toFloat()*2,val gravityX:Float=0f,val gravityY:Float=0f,val size:Float=4f,val color:Rgba=Rgba.WHITE,val seed:Long=1L)
class ParticleSystem(private val emitter:Emitter){private val particles=mutableListOf<Particle>();private var accumulator=0f;private var rng=emitter.seed;fun burst(count:Int){require(count>=0);repeat(count){spawn()}};fun update(dt:Float){require(dt.isFinite()&&dt>=0);accumulator+=emitter.rate*dt;val n=floor(accumulator).toInt();accumulator-=n;repeat(n){spawn()};val it=particles.iterator();while(it.hasNext()){val p=it.next();p.vx+=p.ax*dt;p.vy+=p.ay*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.age+=dt;p.opacity=(1f-p.age/p.life).coerceIn(0f,1f);if(p.age>=p.life)it.remove()}};fun snapshot():List<Particle> =particles.map{it.copy()};private fun spawn(){val u=next().coerceIn(0.000001f,.999999f);val a=(u-.5f)*emitter.spread;val s=emitter.speed*(.75f+.5f*next());particles+=Particle(emitter.x,emitter.y,cos(a)*s,sin(a)*s,emitter.gravityX,emitter.gravityY,0f,max(.001f,emitter.lifetime),emitter.size*(.75f+.5f*next()),0f,1f,emitter.color)};private fun next():Float{rng=rng*6364136223846793005L+1442695040888963407L;return ((rng ushr 40)and 0xffffff).toFloat()/16777216f}}
